372:         b'b' => "bool",
373:         b'c' => "char",
374:         b'e' => "str",
375:         b'u' => "()",
376:         b'a' => "i8",
377:         b's' => "i16",
378:         b'l' => "i32",
379:         b'x' => "i64",
380:         b'n' => "i128",
381:         b'i' => "isize",
382:         b'h' => "u8",
383:         b't' => "u16",
384:         b'm' => "u32",
385:         b'y' => "u64",
386:         b'o' => "u128",
387:         b'j' => "usize",
388:         b'f' => "f32",
